-- Growth Pro foundation: idempotent tables and safe location billing fields.
alter table if exists public.locations add column if not exists growth_pro_override boolean not null default false;
alter table if exists public.locations add column if not exists growth_pro_trial_ends_at timestamptz;
alter table if exists public.locations add column if not exists sms_addon_plan text;
alter table if exists public.locations add column if not exists reservation_mode text not null default 'off';
alter table if exists public.locations add column if not exists reservation_enabled boolean not null default false;
alter table if exists public.locations add column if not exists external_reservation_url text;
alter table if exists public.locations add column if not exists reservation_phone text;
alter table if exists public.locations add column if not exists reservation_owner_email text;

create table if not exists public.location_branding_settings (id uuid primary key default gen_random_uuid(), location_id uuid not null, logo_url text, logo_alt_text text, brand_accent_color text, brand_secondary_color text, theme_key text, hero_image_url text, use_default_theme boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_offerings (id uuid primary key default gen_random_uuid(), location_id uuid not null, offers_food boolean not null default false, offers_drinks boolean not null default false, offers_hookah boolean not null default false, offers_activities boolean not null default false, offers_reservations boolean not null default false, offers_private_events boolean not null default false, offers_group_packages boolean not null default false, offers_catering boolean not null default false, offers_live_events boolean not null default false, offers_tickets boolean not null default false, offers_bottle_service boolean not null default false, primary_offering_type text, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_commerce_pages (id uuid primary key default gen_random_uuid(), location_id uuid not null, page_type text not null, title text not null, external_url text, pdf_url text, description text, hero_image_url text, thumbnail_image_url text, gallery_image_urls jsonb default '[]'::jsonb, is_active boolean not null default true, sort_order integer not null default 0, last_updated_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_commerce_sections (id uuid primary key default gen_random_uuid(), commerce_page_id uuid not null, location_id uuid not null, name text not null, description text, image_url text, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_commerce_items (id uuid primary key default gen_random_uuid(), commerce_page_id uuid not null, section_id uuid, location_id uuid not null, name text not null, description text, price text, image_url text, image_alt_text text, image_source text, tags jsonb default '[]'::jsonb, dietary_tags jsonb default '[]'::jsonb, is_featured boolean not null default false, is_available boolean not null default true, sort_order integer not null default 0, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_qr_codes (id uuid primary key default gen_random_uuid(), location_id uuid not null, code text not null unique, qr_type text not null, destination_path text not null, label text, is_active boolean not null default true, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_qr_scan_events (id uuid primary key default gen_random_uuid(), qr_code_id uuid, location_id uuid not null, qr_type text, outing_id uuid, user_id uuid, guest_session_id text, scanned_at timestamptz default now(), ip_hash text, user_agent text, device_type text, referrer text, metadata jsonb default '{}'::jsonb);
create table if not exists public.location_offers (id uuid primary key default gen_random_uuid(), location_id uuid not null, title text not null, description text, offer_type text, start_date date, end_date date, redemption_instructions text, max_claims integer, is_active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_offer_claims (id uuid primary key default gen_random_uuid(), offer_id uuid not null, location_id uuid not null, customer_name text, customer_email text, customer_phone text, claimed_at timestamptz default now(), redeemed_at timestamptz, status text not null default 'claimed', metadata jsonb default '{}'::jsonb);
create table if not exists public.location_vip_signups (id uuid primary key default gen_random_uuid(), location_id uuid not null, user_id uuid, guest_session_id text, name text, email text, phone text, birthday_month text, interests jsonb default '[]'::jsonb, source text, email_consent boolean not null default false, sms_consent boolean not null default false, consent_text text, consent_ip_hash text, consent_user_agent text, consent_at timestamptz, email_unsubscribed_at timestamptz, sms_unsubscribed_at timestamptz, last_contacted_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_message_templates (id uuid primary key default gen_random_uuid(), template_key text not null unique, channel text not null, category text, title text not null, description text, subject_options jsonb default '[]'::jsonb, body_template text not null, editable_fields jsonb default '[]'::jsonb, locked_fields jsonb default '[]'::jsonb, cta_options jsonb default '[]'::jsonb, requires_admin_approval boolean not null default false, is_active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_messaging_campaigns (id uuid primary key default gen_random_uuid(), location_id uuid not null, created_by uuid, campaign_type text, channel text not null, status text not null default 'draft', name text, subject text, body_rendered text, template_id uuid, template_key text, template_values jsonb default '{}'::jsonb, audience_filter jsonb default '{}'::jsonb, recipient_count integer default 0, scheduled_for timestamptz, sent_at timestamptz, approved_by uuid, approved_at timestamptz, rejected_by uuid, rejected_at timestamptz, rejected_reason text, requires_admin_approval boolean not null default false, sms_credits_estimated integer default 0, sms_credits_used integer default 0, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_messaging_recipients (id uuid primary key default gen_random_uuid(), campaign_id uuid, vip_signup_id uuid, location_id uuid not null, channel text, email text, phone text, status text, sent_at timestamptz, delivered_at timestamptz, opened_at timestamptz, clicked_at timestamptz, failed_at timestamptz, failure_reason text, unsubscribed_at timestamptz, created_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_messaging_custom_requests (id uuid primary key default gen_random_uuid(), location_id uuid not null, created_by uuid, channel text, goal text, audience_filter jsonb default '{}'::jsonb, requested_subject text, requested_body text, business_notes text, desired_send_at timestamptz, status text not null default 'draft', reviewed_by uuid, reviewed_at timestamptz, admin_notes text, approved_subject text, approved_body text, converted_template_id uuid, campaign_id uuid, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_messaging_suppression (id uuid primary key default gen_random_uuid(), location_id uuid not null, email text, phone text, channel text, reason text, source text, created_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_sms_credit_ledger (id uuid primary key default gen_random_uuid(), location_id uuid not null, billing_period_start date, billing_period_end date, credit_type text, credits_added integer not null default 0, credits_used integer not null default 0, credits_remaining integer not null default 0, source text, campaign_id uuid, created_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_notification_recipients (id uuid primary key default gen_random_uuid(), location_id uuid not null, name text, email text not null, phone text, role text not null default 'owner', is_primary boolean not null default false, is_active boolean not null default true, receives_all boolean not null default false, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_notification_preferences (id uuid primary key default gen_random_uuid(), location_id uuid not null, event_type text not null, email_enabled boolean not null default true, dashboard_enabled boolean not null default true, sms_enabled boolean not null default false, digest_only boolean not null default false, recipient_role_filter jsonb default '[]'::jsonb, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_notification_events (id uuid primary key default gen_random_uuid(), location_id uuid not null, event_type text not null, source_table text, source_id text, title text not null, message text, priority text not null default 'normal', status text not null default 'unread', created_at timestamptz default now(), read_at timestamptz, metadata jsonb default '{}'::jsonb);
create table if not exists public.location_notification_deliveries (id uuid primary key default gen_random_uuid(), notification_event_id uuid, location_id uuid not null, recipient_email text, recipient_phone text, channel text, status text not null default 'queued', sent_at timestamptz, failed_at timestamptz, failure_reason text, provider_message_id text, created_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_leads (id uuid primary key default gen_random_uuid(), location_id uuid not null, lead_type text, customer_name text, customer_email text, customer_phone text, occasion text, event_date date, event_time text, guest_count integer, budget_range text, food_needs text, drink_needs text, private_room_needed boolean default false, package_interest text, notes text, status text not null default 'new', source text, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_private_feedback (id uuid primary key default gen_random_uuid(), location_id uuid not null, outing_id uuid, reservation_id uuid, user_id uuid, guest_session_id text, customer_name text, customer_email text, rating integer, feedback_text text, feedback_type text, status text not null default 'new', source text, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.outing_visit_verifications (id uuid primary key default gen_random_uuid(), outing_id uuid, location_id uuid not null, user_id uuid, guest_session_id text, verification_type text, verification_status text, verification_source text, qr_code_id uuid, qr_scan_event_id uuid, reservation_id uuid, review_id uuid, verified_by uuid, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());
create table if not exists public.location_marketing_suggestions (id uuid primary key default gen_random_uuid(), location_id uuid not null, suggestion_type text, title text not null, description text, reason text, recommended_channel text, recommended_audience text, recommended_cta text, source_type text, source_id text, priority text not null default 'normal', status text not null default 'new', valid_from date, valid_until date, used_generation_id uuid, used_campaign_id uuid, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_marketing_generations (id uuid primary key default gen_random_uuid(), location_id uuid not null, created_by uuid, generation_type text, channel text, goal text, source_type text, source_id text, tone text, prompt_inputs jsonb default '{}'::jsonb, generated_content jsonb default '{}'::jsonb, status text not null default 'draft', used_for_campaign_id uuid, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);
create table if not exists public.location_marketing_generation_usage (id uuid primary key default gen_random_uuid(), location_id uuid not null, billing_period_start date, billing_period_end date, generations_included integer not null default 30, generations_used integer not null default 0, flyer_drafts_included integer not null default 5, flyer_drafts_used integer not null default 0, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb default '{}'::jsonb);

create index if not exists idx_location_branding_settings_location on public.location_branding_settings(location_id);
create index if not exists idx_location_offerings_location on public.location_offerings(location_id);
create index if not exists idx_location_commerce_pages_location_active on public.location_commerce_pages(location_id,is_active,sort_order);
create index if not exists idx_location_commerce_items_location_available on public.location_commerce_items(location_id,is_available,sort_order);
create index if not exists idx_location_qr_codes_code_active on public.location_qr_codes(code,is_active);
create index if not exists idx_location_qr_scan_events_location_scanned on public.location_qr_scan_events(location_id,scanned_at desc);
create index if not exists idx_location_offers_location_active on public.location_offers(location_id,is_active);
create index if not exists idx_location_vip_signups_location_created on public.location_vip_signups(location_id,created_at desc);
create index if not exists idx_location_leads_location_status on public.location_leads(location_id,status,created_at desc);
create index if not exists idx_location_notifications_location_status on public.location_notification_events(location_id,status,created_at desc);
